CREATE OR REPLACE FUNCTION public.guardar_visita_prueba(p_negocio uuid,p_socio uuid DEFAULT NULL,p_origen text DEFAULT 'numero',p_tipo text DEFAULT 'nueva',p_gasto text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN IF NOT public.is_super_admin() OR p_negocio IS DISTINCT FROM public.negocio_prueba_actual() THEN RAISE EXCEPTION 'Solo Super admin en acceso de prueba'; END IF; IF p_tipo NOT IN ('nueva','ya_era_clienta') OR p_origen NOT IN ('numero','qr','sin_carnet') OR (p_gasto IS NOT NULL AND p_gasto NOT IN ('lt20','20_50','50_100','gt100')) THEN RAISE EXCEPTION 'Datos no válidos'; END IF; PERFORM set_config('club.test_write','yes',true); INSERT INTO public.visitas(patrocinador_id,socio_id,origen,tipo_cliente,tramo_gasto,es_prueba) VALUES(p_negocio,p_socio,p_origen,p_tipo,p_gasto,true) RETURNING id INTO n; RETURN n; END $$;